\label{main_theorem}
The j.p.d.f. of the eigenvalues of the random matrix~\eqref{eq:tridiagmatrix} is
\begin{equation}
\label{eq:EigDens1}
    P_\beta(\boldsymbol{\lambda}) = \frac{1}{Z_\beta} \prod_{j=1}^n
    \exp\left(-\frac{\left| \lambda_j \right|^2}{2}\right)\prod_{1\le j < k \le n}\left| \lambda_k - 
    \lambda_j \right|^\beta f(\boldsymbol{\lambda}),
\end{equation}
where $\beta\in \mathbb{R}_+$, $Z_\beta$ is a normalization constant,
\begin{equation}
\label{factor}
f(\boldsymbol{\lambda}) =\int_{\mathbb{C}^{n-1}}
\exp\big(-g(\boldsymbol{\lambda},\mathbf{r})\big)
\prod_{j=1}^{n}|r_j|^{\frac{\beta}{2}-2}\prod_{k=1}^{n-1}d^2r_k,
\end{equation}
$\mathbf{r} =(r_1,\dotsc,r_{n}) \in \mathbb{C}^{n}$, $r_n = -r_1 - \dotsb - r_{n-1}$ and
$d^2r_j=\tfrac{i}{2}dr_j \wedge d\bar{r}_j$.  The exponent $g(\boldsymbol{\lambda},\mathbf{r})$ is 
a positive function defined by 
\begin{equation}
g(\boldsymbol{\lambda},\mathbf{r}) =  \frac{1}{2}\left(\sum_{j=1}^n \left| a_j \right|^2 + \sum_{j=1}^{n-1}\left| b_j \right|^2 
        + n - 1\right) - \frac{1}{2}\sum_{j =1}^n \left| \lambda_j \right|^2,
\end{equation}
where the $a_j$s and $b_k$s are rational functions of $\lambda_1,\dotsc,\lambda_n$ and $r_1,\dotsc,r_{n-1}$,
and can be reconstructed interactively from the recurrence relations~\eqref{eq:sol_rec_rn}. 
(See Theorem~{\rm \ref{theorem:inversion}}.) Furthermore, we have
\begin{enumerate}
\item  $g(\boldsymbol{\lambda},\mathbf{r}) = O\left( \left| \lambda_j \right|^4\right)$ as $\lambda_j \to \infty$, \quad $j=1,\dotsc,n$;
\item $g(\boldsymbol{\lambda} e^{i\psi},\mathbf{r})=g(\boldsymbol{\lambda},\mathbf{r})$, \quad   
 $\,\psi \in [0,2\pi)$.
\end{enumerate}

\label{parameterization}
Let $\mathbf{r} = (r_1,\dots,r_n)$ and $\mathbf{v}=(v_1,\dotsc,v_n)$ be the first 
and last row of  $R\in R'(n)$, respectively. We have 
\begin{equation}
    \label{el_diff_from_zero}
        r_j \neq 0, \quad  v_j \neq 0 \quad \text{for all}  \quad j \in \left \{1,\dotsc,n\right\}.
\end{equation}
Furthermore, the subset of $R'(n)$  such that 
\begin{equation}
    \label{hyperp_1}
        r_1 + \dotsb + r_n =1
\end{equation}
spans a set of representatives in $\mathcal{R}'(n)$.

Let us take  $T\in \mathcal{T}'(n)$ and let
\begin{equation}
    \label{princ_subm}
        T_k = \begin{pmatrix}
                 a_n & 1 &  &  \\
                 b_{n-1} & a_{n-1} & \ddots &  \\
                 & \ddots & \ddots & 1 \\
                 &  & b_{n-k+1} & a_{n-k+1} 
              \end{pmatrix}
\end{equation}
be the principal submatrix of $T$ obtained by removing the last $n-k$ rows and columns. Note that
$T_n=T$. Let $\lambda_j^{(k)}$, $j=1,\dotsc,k$, denote the eigenvalues of $T_k$ and write
\begin{equation}
\label{cp_sm1}
    \Phi_k(x) = \det\left(x I - T_{k}\right) = 
                 \prod_{j=1}^k\Bigl(x-\lambda_j^{(k)}\Bigr).
\end{equation}
The characteristic polynomials $\Phi_k$ obey the recurrence relation 
\begin{equation}
    \label{rec_rel1}
        \Phi_{k}(x) = (x - a_{n-k +1 })\Phi_{k-1}(x) - b_{n-k +1 }\Phi_{k-2}(x), \quad k=1,\dotsc, n,
\end{equation}
with initial conditions 
\begin{equation}
    \label{in_con}   
        \Phi_{0}(x)=1,  \quad \Phi_{-1}(x)=0
\end{equation}
and $b_n$ undetermined.  Equation~\eqref{cp_sm1} implies that $\lambda_j =\lambda_j^{(n)}$ is
an eigenvalue of $T$ and that
\begin{equation}
    \label{right_eig}
        \begin{pmatrix} 
            \Phi_0\bigl(\lambda_j\bigr)\\ 
            \vdots \\
            \Phi_{n-1}\bigl( \lambda_j\bigr) 
        \end{pmatrix}
\end{equation}
is the right-eigenvector corresponding to $\lambda_j$.  Furthermore, by 
definition, the matrix 
\begin{equation*}
    R= \begin{pmatrix}
            \Phi_0\bigl(\lambda_1\bigr) & \cdots & \Phi_0\bigl(\lambda_n\bigr)\\
            \Phi_1\bigl(\lambda_1\bigr) & \cdots & \Phi_1\bigl(\lambda_n\bigr)\\
             \hdotsfor[2]{3}\\
            \Phi_{n-1}\bigl(\lambda_1\bigr)& \cdots & 
             \Phi_{n-1}\bigl(\lambda_n\bigr)
        \end{pmatrix}
\end{equation*}
belongs to $R'(n)$. If there is no degeneracy in the spectrum, the eigenvectors are unique
up to a multiplication by a constant.  Since $\Phi_0\bigl(\lambda_j\bigr)=1,$ it follows that
$r_j\neq 0$ for $j=1,\dotsc,n.$

In order to show that $v_j\neq 0$, suppose that 
\[
    \Phi_{n-1}\bigl(\lambda_j\bigr)= 0 \quad  \text{for some} \quad 
    j \in \{1,\dotsc,n\}.
\]
Since $b_{j}\neq 0$, $j=1,\dotsc,n-1$, it  follows by induction that all the entries 
of~\eqref{right_eig} are zero and that $\det R = 0$, which contradicts the assumption that the 
spectrum is simple. 

We now want to show that
\begin{equation}
    \label{setrep}
        L = \left\{ R \in R'(n) \colon  r_1 + \dotsb + r_n =1\right\}
\end{equation}
is a set of representatives of $R'(n)$. Suppose that the elements of the first column of $R^{-1}$ are all 
different from zero. Then,  Eq.~\eqref{hyperp_1} follows from the identity $RR^{-1}=I$ and from the fact that 
matrices in the same equivalent class of $\mathcal{R}'(n)$ differ by the right multiplication  $R \mapsto RD$, where
$D\in D(n).$ The proof that the elements of the first column of $R^{-1}$ are all different from zero 
follows similar lines to those that we have used to prove 
Eq.~\eqref{el_diff_from_zero}.

Take the principal submatrix of $T$ obtained by removing the first $n-k$ rows and columns,
\begin{equation}
    \label{princ_subm_2}
        U_k = \begin{pmatrix}
                a_k & 1 &  &  \\
                b_{k-1} & a_{k-1} & \ddots &  \\
                 & \ddots & \ddots & 1 \\
                 &  & b_1 & a_1 
              \end{pmatrix}.
\end{equation}
Let $\mu_j^{(k)}$, $j=1,\dotsc,k$, denote the eigenvalues of $U_k$ and write
\begin{equation}
    \label{cp_sm2}
        \chi_k(x) = \det\left(x I - U_{k}\right) = 
        \prod_{j=1}^k\Bigl(x-\mu_j^{(k)}\Bigr).
\end{equation}
We have that $\lambda_{j}= \mu^{(n)}_{j}.$ The polynomials $\chi_k$ obey the recurrence relation 
\begin{equation}
\label{rec_rel2}
\chi_k(x) = (x - a_k)\chi_{k-1}(x) -b_{k-1}\chi_{k-2}(x), \quad k=1,\dotsc,n,
\end{equation}
with initial conditions 
\[
\chi_{0}(x)=1, \quad  \chi_{-1}(x)=0
\]
and $b_0$ undetermined.  Equation~\eqref{rec_rel2} and
\[
    \chi_n\bigl(\lambda_j\bigr)=0, \quad j=1,\dotsc,n,
\]
imply that 
\begin{equation}
    \label{left_eig}
        \left(\chi_{n-1}\bigl(\lambda_j\bigr),\dotsc, \chi_0\bigl( \lambda_j\bigr) \right)
\end{equation}
is the left eigenvector corresponding to $\lambda_j$ and is proportional to the $j$-th row of $R^{-1}.$ 
The same arguments that led to the conclusion that $\Phi_{n-1}\bigl(\lambda_j\bigr)\neq 0$ give
$\chi_{n-1}\bigl(\lambda_j\bigr)\neq 0.$

Take $R$ from the set of representative of $\mathcal{R}'(n)$ defined in Lemma~\ref{parameterization}. Let us 
write the matrix equations
\[
TR = R\Lambda \quad \text{and} \quad  R^{-1}T = \Lambda R^{-1}
\]
as a set of vector equations:
\begin{subequations}
\label{eq:rec_r}
\begin{align}
\label{eq:rec_ra}
\mathbf{r}_j^t\Lambda  & = b_{n-j+1}\mathbf{r}_{j-1}^t + a_{n-j+1}\mathbf{r}_j^t + \mathbf{r}_{j+ 1}^t, \\
\label{eq:rec_rb}
\Lambda\mathbf{l}_j & = \mathbf{l}_{j-1} + a_{n-j+1}\mathbf{l}_j +b_{n-j}\mathbf{l}_{j+1},
\end{align}
\end{subequations}
for $j=1,\dotsc,n$, where we have adopted the notation~\eqref{eq:newnot}.  Let
$\mathbf{r}_1=\mathbf{r}$ and

We want to show that given $\Lambda$ and $\mathbf{r}_1^t$ with $\mathbf{r}^t_1\mathbf{l}_1=1$, where 
\[
    \mathbf{l}_1 = \begin{pmatrix}
        1 \\ \vdots \\ 1
    \end{pmatrix},
\]
we can reconstruct $T$, $R$ and $R^{-1}$ uniquely from the recurrence relations~\eqref{eq:rec_r} with boundary conditions $b_n=0$ and $\mathbf{l}_0=\mathbf{0}$,
$\mathbf{r}_{n+1}^t=\mathbf{0}$. The vectors $\mathbf{r}_0^t$ and $\mathbf{l}_{n+1}$ are undetermined.

Write
\begin{subequations}
\label{eq:sol_rec_r1}
\begin{align}
\label{eq:an}
a_n & = \mathbf{r}_1^t \Lambda \mathbf{l}_1,\\
\label{eq:r2}
\mathbf{r}_2^t & = \mathbf{r}_1^t \Lambda - a_n \mathbf{r}_1^t,\\
\label{eq:bn1}
   b_{n-1} & = \mathbf{r}_2^t \Lambda   \mathbf{l}_1,\\
   \label{eq:l2}
        \mathbf{l}_2 &= \frac{1}{b_{n-1}}\left(\Lambda  \mathbf{l}_1 - a_n \mathbf{l}_1\right).
\end{align}
\end{subequations}
For any fixed $\Lambda,$ the set exceptional points $\mathbf{r}_1$ such that $b_{n-1}=0$ has measure zero 
in $\mathcal{H}_n$ and can be neglected. The quantities $a_n$, $b_{n-1}$, $\mathbf{r}_1^t$ and $\mathbf{l}_1$ solve~\eqref{eq:rec_r}
for $j=1$. We need to check that they are consistent with the 
condition $RR^{-1} = I$. Eqs.\eqref{eq:an} and~\eqref{eq:r2} give $\mathbf{r}_2^t  \mathbf{l}_1=0$. Similarly, by 
Eqs.~\eqref{eq:an} and~\eqref{eq:l2} we have $\mathbf{r}_1^t  \mathbf{l}_2 =0$.  Finally, we have
\begin{equation*}
    \mathbf{r}_2^t  \mathbf{l}_2 =  \frac{1}{b_{n-1}} \left(\mathbf{r}_2^t \Lambda 
    \mathbf{l}_1 - a_n\mathbf{r}_2^t  \mathbf{l}_1\right) = 1.
\end{equation*}
Note that combining the orthogonality relations $\mathbf{r}_1^t \mathbf{l}_2 = 0$ and $\mathbf{r}_2^t \mathbf{l}_2=1$ with Eq.~\eqref{eq:r2} gives
\[
\mathbf{r}_1^t  \Lambda  \mathbf{l}_2 = 1,
\]
as it should be. 

When $1<j<n$ take 
\[
\mathbf{r}_{j-1}^t,\; \mathbf{r}_j^t,\; \mathbf{l}_{j- 1},\; \mathbf{l}_j
\]
subject to the conditions
\begin{subequations}
\label{eq:int_ic}
\begin{gather}
\mathbf{r}^t_j \mathbf{l}_j= \mathbf{r}^t_{j-1}\mathbf{l}_{j-1}=1, \quad \mathbf{r}^t_j \mathbf{l}_{j-1}= \mathbf{r}^t_{j-1} \mathbf{l}_{j}=0,\\
b_{n - j +1} = \mathbf{r}_{j}^t  \Lambda \mathbf{l}_{j-1} \neq 0, \quad \mathbf{r}_{j-1}^t \Lambda \mathbf{l}_{j}=1.
\end{gather}
\end{subequations}
Define
\begin{subequations}
\label{eq:sol_rec_rn}
\begin{align}
\label{eq:anj}
a_{n-j+1} & = \mathbf{r}_j^t \Lambda  \mathbf{l}_j,\\
\label{eq:rj}
\mathbf{r}_{j+1}^t & =  \mathbf{r}_j^t \Lambda - a_{n - j + 1}\mathbf{r}_j^t - b_{n-j+1}\mathbf{r}_{j-1}^t\\
\label{eq:bnj}
   b_{n-j} & = \mathbf{r}_{j+1}^t  \Lambda   \mathbf{l}_j,\\
   \label{eq:lj}
        \mathbf{l}_{j+1} &= \frac{1}{b_{n-j}}\left(\Lambda  \mathbf{l}_j- a_{n - j +1}\mathbf{l}_j-\mathbf{l}_{j-1}\right).
\end{align}
\end{subequations}
For any fixed $\Lambda$, we have $b_{n-j}=0$ for $\mathbf{r}_{j+1}$ and $\mathbf{l}_j$ belonging to a set of measure zero in ${\mathbb C}^n.$ 
In turn, $\mathbf{r}_{j+1}$ and $\mathbf{l}_j$ are rational functions of the elements of $\mathbf{r}_1$; therefore,  $b_{n-j}=0$ only for 
$\mathbf{r}_1$ belonging to a set of  measure zero in $\mathcal{H}_n.$ Combining~\eqref{eq:int_ic} with~\eqref{eq:sol_rec_rn} and
proceeding in a similar way as when $j=1$, we can show that
\begin{align*}
\mathbf{r}_{j+1}^t \mathbf{l}_{j} &= 0, & \mathbf{r}_{j+1}^t  \mathbf{l}_{j-1}& =0,\\
\mathbf{r}_{j}^t \mathbf{l}_{j+1} &= 0, & \mathbf{r}_{j-1}^t  \mathbf{l}_{j+1}&=0.
\end{align*}
Furthermore, we have
\begin{align*}
\mathbf{r}_{j+1}^t \mathbf{l}_{j+1}& = \frac{1}{b_{n-j}}\left(\mathbf{r}_{j+1}^t 
\Lambda  \mathbf{l}_j- a_{n - j +1}
\mathbf{r}_{j+1}^t \mathbf{l}_j-\mathbf{r}_{j+1}^t \mathbf{l}_{j-1}\right)=1\\
\mathbf{r}_{j}^t   \Lambda   \mathbf{l}_{j+1} & = b_{n-j+1}\mathbf{r}_{j-1}^t  \mathbf{l}_{j+1}
+ a_{n-j+1}\mathbf{r}_j^t  \mathbf{l}_{j+1}+ \mathbf{r}^t_{j+ 1} \mathbf{l}_{j+1} =1.
\end{align*}
The orthogonality relations
\[
\mathbf{r}_{j+1}^t  \mathbf{l}_{k}=0, \quad \mathbf{r}_k^t  \mathbf{l}_{j+1}=0, \quad k=1, \dotsc, j-2
\]
follow by induction and from the fact that by construction $\mathbf{r}^t_j \Lambda \mathbf{l}_k = 0$ if $\left| j-k \right|>1$.

The boundary condition $\mathbf{r}^t_{n+1}=\mathbf{0}$ terminates the recurrence relations.

\label{thm:jac}
We have
\begin{equation*}
\prod_{k=1}^{n-1}d^2b_k\prod_{j=1}^n d^2a_j=\frac{\prod_{j=1}^{n-1}\left| b_j \right|^2}{\prod_{k=1}^n 
\left| r_k \right|^2}\prod_{k=1}^{n-1}d^2r_k\prod_{j=1}^n d^2\lambda_j .
\end{equation*}

\label{prop}
Let $j=1,\dotsc,n-1.$ The following statements hold:
\begin{enumerate}
    \item $\bigl|\widetilde{b}_{n-1}\widetilde{b}_{n-2}\dotsm \widetilde{b}_{n-j}\bigr|=
    \bigl \|\chi_j(\widetilde{T})\mathbf{e}_1\bigr \|=\underset{\psi \in \mathcal{P}_j[\mathbb{C}]}
    {\min}\bigl \|\psi(\widetilde{T})\mathbf{e}_1\bigr \|$;
    \item $\chi_j(\widetilde{T})\mathbf{e}_1=\mathbf{e}_{j+1}\widetilde{b}_{n-1}\widetilde{b}_{n-2}\dotsm \widetilde{b}_{n-j}$;
    \item $|c_{n-1}c_{n-2}\dotsm c_{n -j}|=
    \bigl \|\mathbf{e}_1^t\chi_j(\widetilde{T})\bigr \|=\underset{\psi \in \mathcal{P}_j[\mathbb{C}]}
    {\min}\bigl \|\mathbf{e}_1^t\psi(\widetilde{T})\bigr\|$;
    \item $\mathbf{e}_1^t\chi_j(\widetilde{T})= \mathbf{e}_{j+1}^tc_{n-1}c_{n-2}\dotsm c_{n-j}$.
\end{enumerate}

The definition of $T$ and Proposition~\ref{prop} give
\begin{subequations}
\label{eq:minstat}
\begin{align}
\label{eq:lem231}
\chi_j(T)\mathbf{e}_1 & =\mathbf{e}_{j+1}b_{n-1}b_{n-2}\dotsm b_{n-j},\\
\label{eq:lem232}
    \mathbf{e}_1^t\chi_j(T) &= \mathbf{e}_{j+1}^t,
\end{align}
\end{subequations}
for $j=1,2,\dotsc,n-1$.  Using the spectral decomposition $T = R\Lambda R^{-1}$ and the definition of $R$ given in~\eqref{eq:newnot}, Eqs.~\eqref{eq:minstat} become
\begin{align*}
\chi_j(\Lambda)R^{-1}\mathbf{e}_1 & = \chi_j(\Lambda) \mathbf{l}_1 = R^{-1}\mathbf{e}_{j+1}b_{n-1}b_{n-2}\dotsm b_{n-j} \nonumber \\
& = \mathbf{l}_{j+1}b_{n-1}b_{n-2} \dotsm b_{n-j},\\
    \mathbf{e}_1^tR\chi_j(\Lambda) &= \mathbf{r}_1^t\chi_j(\Lambda) = \mathbf{e}_{j+1}^t R  = \mathbf{r}_{j+1}^t.
\end{align*}
Multiplying these equations side by side gives 
\[
\mathbf{r}_1^t\chi_j(\Lambda)  \chi_k(\Lambda)\mathbf{l}_1 = 
\mathbf{r}_{j+1}^t  \mathbf{l}_{k+1}\prod_{m=1}^k b_{n-m},
\]
which can be rewritten as 
\begin{equation}
\label{eq:lem235}
\sum_{l=1}^n r_l\chi_j(\lambda_l)\chi_k(\lambda_l)=
\begin{cases} 1 & \text{if $j=k=0$,} \\
\delta_{jk}\prod_{m=1}^k b_{n-m}, & \text{if $j \neq 0$ or $k \neq 0$,}
\end{cases}
\end{equation}
for $j,k=0,\dotsc, n-1$, where we have used $\mathbf{l}_1^t = (1,\dotsc,1)$ and the fact that by 
definition $\chi_0(z)=1.$

Write
\begin{equation*}
    W = \begin{pmatrix} 1 & \chi_1(\lambda_1) & \dots &\chi_{n-1} (\lambda_{1}) \\
                        1 & \chi_1(\lambda_2) & \dots &\chi_{n-1} (\lambda_{2}) \\
                        \hdotsfor[2]{4}\\
                        1 & \chi_1(\lambda_n) & \dots &\chi_{n-1} (\lambda_{n}) \\
         \end{pmatrix}                        
\end{equation*}
and
\begin{equation*}
    Q = \begin{pmatrix} r_1 & & & \\
    & r_2 & &  \\
    & & \ddots& \\
    & &  & r_n 
    \end{pmatrix},  \quad 
    B = \begin{pmatrix} 1 & & & \\
    & b_{n-1} & &  \\
    & & \ddots& \\
    & &  & \prod_{m=1}^{n-1} b_{n-m} 
    \end{pmatrix}.
\end{equation*}
Eq.~\eqref{eq:lem235} is the matrix product
\begin{equation*}
    W^t Q W = B
\end{equation*}
written in terms of matrix elements.  Since $\det(W) = \Delta(\boldsymbol{\lambda})$, taking the determinant of both sides of this equation gives
\[
\prod_{1\le j<k\le n}\left(\lambda_k-\lambda_j\right)^2 
\prod_{j=1}^n r_j = \prod_{k=1}^{n-1} b_k^k.
\]

\label{lem:jac2}
 We have
\begin{equation}
\label{jac_abrlb}
  \prod_{j=1}^{n-1}b_{j}^{2j-1}  d\mathbf{a} \wedge d\mathbf{b} =  
  \left(\prod_{k=1}^n r_k\right) \Delta(\boldsymbol{\lambda})^4 d\mathbf{r} \wedge d\boldsymbol{\lambda}.
\end{equation}

Write
\begin{equation*}
    ((I_n-zT)^{-1})_{11}=\sum_{j=1}^n\frac{r_j}{1-z\lambda_j}, 
\end{equation*}
and take the Taylor expansion of both sides of this equation. By equating the coefficients of the powers of $z$ up to $z^{2n-1}$ we arrive at
\begin{equation}
  \label{eq:Taylor_exps}
\begin{split}
    O(z^0):&\hspace{3mm}1=\sum_{j=1}^nr_j\\
    O(z^1):&\hspace{3mm}a_n=\sum_{j=1}^nr_j\lambda_j\\
    O(z^2):&\hspace{3mm}*\;+b_{n-1}=\sum_{j=1}^nr_j\lambda_j^2\\
    O(z^3):&\hspace{3mm}*\;+a_{n-1}b_{n-1}=\sum_{j=1}^nr_j\lambda_j^3\\
    O(z^4):&\hspace{3mm}*\; +b_{n-1}b_{n-2}=\sum_{j=1}^nr_j\lambda_j^4\\
    O(z^5):&\hspace{3mm}*\;+a_{n-2}b_{n-1}b_{n-2}=\sum_{j=1}^nr_j\lambda_j^5\\
    \vdots \hspace{.6cm} & \hspace{1.8cm}\vdots \hspace{2.5cm}\vdots\\
    O(z^{2n-1}):&\hspace{3mm}*\; +a_1b_1\dots b_{n-1}=\sum_{j=1}^nr_j\lambda_j^{2n-1}.
\end{split}
\end{equation}

The symbol  $*$ in Eqs.~\eqref{eq:Taylor_exps} 
indicates polynomials in which only the
$a_j$s and $b_k$s contained in lower order terms appear.
Therefore, if we choose the ordering
\[
a_n,  b_{n-1}, a_{n-1}, b_{n-2}, \dotsc, b_1,a_1,
\]
the matrix of the coefficients of the differentials of the left-hand sides of Eqs.~\eqref{eq:Taylor_exps} is triangular.  Taking the wedge product line by
line gives 
\begin{equation}
\label{eq:wplhs}
(-1)^{(n-1)(n-2)/2} \left(\prod_{j=1}^{n-1}b_j^{2j-1} \right)d\mathbf{a} \wedge d\mathbf{b}.
\end{equation}

Differentiating the right-hand sides of Eqs.~\eqref{eq:Taylor_exps} leads to
\begin{equation}
\label{eq:diffrhs}
d\left(\sum_{k=1}^nr_k\lambda_k^{j}\right)=\sum_{k=1}^{n-1}dr_k(\lambda_k^{j}-\lambda_n^{j})+j\sum_{k=1}^nr_k\lambda_k^{j-1}d\lambda_k,
\end{equation}
where we have used the relation
\begin{equation*}
    dr_n = - \sum_{j=1}^{n-1} dr_j,
\end{equation*}
which follows from the first equation in~\eqref{eq:Taylor_exps}. Taking 
the wedge product of the right-hand side of Eq.~\eqref{eq:diffrhs} 
for $j=1,\dotsc, 2n-1$ we arrive at 
\begin{equation}
\label{eq:jac:2}
    \left(\prod_{k=1}^nr_k \right)
    \det\bigg(\left(\lambda_k^j-\lambda_n^j\right)_{
    \begin{subarray}{l}
          j=1,\dotsc,2n-1 \\ k=1,\dotsc,n-1
     \end{subarray}}
     \left(j\lambda_k^{j-1}\right)_{
       \begin{subarray}{l}
          j=1,\dotsc,2n-1 \\ k=1,\dotsc,n
     \end{subarray}}
     \bigg)d \mathbf{r} \wedge d\boldsymbol{\lambda}. 
\end{equation}
The determinant in this equation can be calculated explicitly and is found as
Eq.~(1.175) in the book by Forrester~\cite{For10}.
We have
\begin{gather*}
(-1)^{(n-1)(n-2)/2}\det\bigg(\left(\lambda_k^j-\lambda_n^j\right)_{
    \begin{subarray}{l}
          j=1,\dotsc,2n-1 \\ k=1,\dotsc,n-1
     \end{subarray}}
     \left(j\lambda_k^{j-1}\right)_{
       \begin{subarray}{l}
          j=1,\dotsc,2n-1 \\ k=1,\dotsc,n
     \end{subarray}}
     \bigg) \nonumber \\
     \label{eq:crazy_det}
     = \prod_{1 \le j < k \le n}\left(\lambda_k - \lambda_j\right)^4 = \Delta(\boldsymbol{\lambda})^4.
\end{gather*}
Eqs.~\eqref{eq:wplhs} and~\eqref{eq:jac:2} give
\begin{equation*}
    \label{jacobiand_eq}
     \left(\prod_{j=1}^{n-1}b_j^{2j-1} \right)d\mathbf{a} \wedge d\mathbf{b} 
       =  \left(\prod_{k=1}^nr_k \right) \Delta(\boldsymbol{\lambda})^4 d\mathbf{r} \wedge d\boldsymbol{\lambda},
\end{equation*}
which leads to~\eqref{jac_abrlb}.

The canonical vector 
    \[
    \mathbf{e}_1 = \begin{pmatrix} 1 \\  \vdots \\ 0 \end{pmatrix}
    \]
    is cyclic for $T$; therefore, 
    \begin{equation}
       \label{lin_ind}
       \mathbf{e}_1, \, T\mathbf{e}_1, \dotsc,\, T^{n-1}\mathbf{e}_1
    \end{equation}
    are linearly independent. As a consequence, $T^n\mathbf{e}_1$ has a 
    unique representation as a linear combination of the vectors~\eqref{lin_ind}.  Equivalently, 
    there exists a unique monic polynomial $\chi_n$ of degree $n$ such that $\chi_n(T)\mathbf{e}_1=0$. Furthermore, $\chi_n(T)$ is the polynomial in $T$ of 
    least degree that annihilates $\mathbf{e}_1$. Next, let
    $\phi$ be the minimal polynomial of $T$. It satisfies the following properties:
    \begin{enumerate}
      \item $\phi(T)=0 \implies \phi(T)\mathbf{e}_1=0$;
      \item by the Calyley-Hamilton theorem, the degree of $\phi$ cannot exceed $n$;
      \item $\phi$ is a divisor of the characteristic polynomial of $T$.
    \end{enumerate}
    Thus, it follows that $\chi_n = \phi$ is both the minimal and 
    the characteristic polynomial of $T$. Thus, the spectrum of $T$ is either simple, or, if  $\lambda$ is a multiple root of $\chi_n$, then it has only one block in the Jordan
    normal form of $T$.

Let $\mu\neq\lambda_j$, for all $j=1,\dotsc,n$, so that the 
resolvent $(\mu I-\widetilde{T})^{-1}$ is well defined. We have
\begin{equation}
\label{eq:appendix:limit}
\begin{split}
    \operatorname{adj} \left(\mu I-\widetilde{T}\right)&=
    \det(\mu I-\widetilde{T})(\mu I-\widetilde{T})^{-1}\\
    &=\chi(\mu)(\mu I-R\Lambda R^{-1})^{-1} \\
    &=R\Delta(\mu)R^{-1},
\end{split}
\end{equation}
where $\Delta(\mu)=\operatorname{diag}(\delta_1(\mu),\dotsc,\delta_n(\mu))$ and
\begin{equation*}
\delta_k(\mu)=\frac{\chi(\mu)}{\mu-\lambda_k}=
\prod_{\substack{i=1\\i\neq k}}^n(\mu-\lambda_i).
\end{equation*}
Taking the limit as $\mu\rightarrow\lambda_j$ of both sides of 
$\eqref{eq:appendix:limit}$ yields
\[
\text{adj}\left(\lambda_j I-\widetilde{T}\right)
=R\Delta(\lambda_j)R^{-1},
\]
where
\begin{align*}
\delta_k(\lambda_j)=\begin{cases}
0&\text{for $k\neq j$},\\
\prod_{i\neq j}(\lambda_j-\lambda_i)=\chi'(\lambda_j)&\text{for $k=j$.}
\end{cases}
\end{align*}

\label{theorem:spec}
Let $R_{rj}=\mathbf{e}_r^t\mathbf{R}_j$ and $L_{js}=\mathbf{L}_j^t\mathbf{e}_s$,
where $j,r,s=1,\dotsc,n$. Then, we have
\begin{equation}
\label{devrel}
    \chi'(\lambda_j)R_{rj}L_{j s} =\begin{cases}
    \chi_{n-s,1}(\lambda_j)c_{n-r}\chi_{n,n-r+2}(\lambda_j)&
    \text{if $s-r=1$, }\\
    \chi_{n-s,1}(\lambda_j)c_{n-s+1}\dotsm c_{n-r}\chi_{n,n-r+2}(\lambda_j)&
    \text{if $s-r>1$, }\\
    \chi_{n-r,1}(\lambda_j) \widetilde{b}_{n-s}\chi_{n,n-s+2}(\lambda_j)&\text{if $r-s=1$,}\\
    \chi_{n-r,1}(\lambda_j)\widetilde{b}_{n-r+1}\dotsm \widetilde{b}_{n-s}\chi_{n,n-s+2}(\lambda_j)&\text{if $r-s>1$,}\\
    \chi_{n-r,1}(\lambda_j)\chi_{n,n-r+2}(\lambda_j) & \text{if $r=s$.}
    \end{cases}
\end{equation}
